// Builds the ARABIC Brand & Franchise Starter Kit (RTL, clean menu-style design) → brand-kit-ar/
// Run: npm run kit:ar   (rename: BRAND_NAME="X" AR_DESCRIPTOR="..." AR_SLOGAN="..." npm run kit:ar)
import { mkdirSync, writeFileSync, readdirSync, rmSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";
import { categories, products, margin } from "../src/data/menu.ts";
import { standardRecipes } from "../src/data/standard-recipes.ts";
import { ar, arCategories, arQty, arTemp, arSize } from "../src/data/menu.ar.ts";
import { palette } from "../src/data/brand.ts";

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const KIT = path.join(ROOT, "brand-kit-ar");
const ASSETS = path.join(KIT, "assets");
const NAME = (process.env.BRAND_NAME ?? "Aurevo").trim();
const DESC = (process.env.AR_DESCRIPTOR ?? "بيت قهوة الساعة الذهبية").trim();
const SLOGAN = (process.env.AR_SLOGAN ?? "تمهّل… وتألّق").trim();
const SLUG = NAME.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "brand";
const DOMAIN = `${SLUG}.example`;
const esc = (s = "") => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const usd = (n) => `${Number(n).toFixed(2)} $`;
const T = (s = "") => String(s).replaceAll("Aurevo", NAME);

// ------------------------------------------------------------------ 1. artwork (Arabic text variants)
rmSync(ASSETS, { recursive: true, force: true });
mkdirSync(path.join(ASSETS, "kit"), { recursive: true });
const env = { ...process.env, BRAND_LANG: "ar", BRAND_NAME: NAME, BRAND_DESCRIPTOR: DESC, BRAND_SLOGAN: SLOGAN, ART_OUT: ASSETS };
execFileSync("node", ["scripts/generate-art.mjs"], { cwd: ROOT, env, stdio: "pipe" });
process.env.BRAND_LANG = "ar"; // kit-art reads this at import time
const { cupSizesSvg, flagshipPlanSvg, kioskPlanSvg } = await import("./kit-art.mjs");
writeFileSync(path.join(ASSETS, "kit/cup-sizes.svg"), cupSizesSvg());
writeFileSync(path.join(ASSETS, "kit/floorplan-flagship.svg"), flagshipPlanSvg());
writeFileSync(path.join(ASSETS, "kit/floorplan-kiosk.svg"), kioskPlanSvg());

// ------------------------------------------------------------------ 2. helpers
let uid = 0;
/** Inline an SVG (so page fonts apply to its Arabic text); ids are namespaced to avoid collisions. */
const inline = (rel, { cls = "", recolor } = {}) => {
  let s = readFileSync(path.join(ASSETS, rel), "utf8").replace(/<\?xml[^>]*\?>/, "");
  const n = ++uid;
  const ids = [...s.matchAll(/ id="([^"]+)"/g)].map((m) => m[1]);
  for (const id of ids) s = s.replaceAll(` id="${id}"`, ` id="${id}-${n}"`).replaceAll(`url(#${id})`, `url(#${id}-${n})`).replaceAll(`href="#${id}"`, `href="#${id}-${n}"`);
  s = s.replace(/<svg([^>]*?) width="[\d.]+" height="[\d.]+"/, "<svg$1");
  if (recolor) s = s.replaceAll("#1B120D", recolor);
  return s.replace("<svg", `<svg class="${cls}" preserveAspectRatio="xMidYMid meet"`);
};
const img = (rel, cls = "") => `<img class="${cls}" src="../assets/${rel}" alt="">`;
const rgb = (hex) => { const n = parseInt(hex.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const cmyk = (hex) => { const [r, g, b] = rgb(hex).map((v) => v / 255); const k = 1 - Math.max(r, g, b); if (k === 1) return [0, 0, 0, 100]; return [(1 - r - k) / (1 - k), (1 - g - k) / (1 - k), (1 - b - k) / (1 - k), k].map((v) => Math.round(v * 100)); };
const arRec = (p) => {
  const e = ar[p.slug] ?? { name: p.name };
  const en = p.ingredients?.length ? { ingredients: p.ingredients, method: p.method ?? [], note: "", yield: "" } : { ingredients: standardRecipes[p.slug]?.ingredients ?? [], method: standardRecipes[p.slug]?.method ?? [], note: standardRecipes[p.slug]?.note, yield: standardRecipes[p.slug]?.yield };
  return { ingredients: en.ingredients.map((x, i) => ({ item: e.ing?.[i] ?? x.item, qty: arQty(x.qty) })), method: e.method ?? en.method, note: e.note ?? "", yield: e.yield ?? "" };
};
const sig = products.filter((p) => p.tier === "signature");
const classics = products.filter((p) => p.tier === "classic");
const catName = (slug) => arCategories[slug]?.name ?? slug;

const pages = [];
const add = (section, html, theme = "") => pages.push({ section, html, theme });
const head = (eyebrow, title, sub = "") => `<div class="hd"><span class="chip">${esc(eyebrow)}</span><h2>${title}</h2>${sub ? `<p class="sub">${esc(sub)}</p>` : ""}</div>`;
const ul = (a) => `<ul>${a.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>`;
const card = (title, body, cls = "") => `<div class="card ${cls}"><h3>${title}</h3>${body}</div>`;
const tbl = (rows, cols, cls = "") => `<table class="${cls}"><thead><tr>${cols.map((c) => `<th>${esc(c)}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
const note = (t) => `<div class="note">${t}</div>`;
const divider = (n, title, sub) => add(title, `<div class="div"><span class="dn">${String(n).padStart(2, "0")}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p><svg class="arc" viewBox="0 0 200 100"><path d="M10 100 A90 90 0 0 1 190 100 Z" fill="#C9873A"/></svg></div>`, "dark");
const catBar = (active) => `<div class="cats">${categories.map((c) => `<div class="cat${c.slug === active ? " on" : ""}"><i>${inline(`icons/${c.slug}.svg`, { recolor: "#C9873A" })}</i><span>${esc(catName(c.slug))}</span></div>`).join("")}</div>`;

// ------------------------------------------------------------------ 3. pages
add("الغلاف", `<div class="cover"><div class="cv-top"><img class="clogo" src="../assets/logo/logo-primary-light.svg" alt=""><span class="badge">النسخة 1.0 · مرحلة المفهوم</span></div>
<div class="cv-mid"><p class="eyebrow">دليل العلامة التجارية والامتياز</p><h1>${esc(DESC)}</h1><p class="cv-sub">«${esc(SLOGAN)}»</p></div>
<svg class="cv-arc" viewBox="0 0 200 100"><path d="M10 100 A90 90 0 0 1 190 100 Z" fill="#C9873A"/></svg>
<p class="cv-fine">كل ما في هذا الدليل مقترح: الوصفات لم تُجرَّب، والأسعار والأرقام المالية تقديرات، والاسم لم يُفحص كعلامة تجارية رسمية، ولا يوجد امتياز معروض حالياً. انظر الصفحة 5.</p></div>`, "dark");
