add("فكرة العلامة", `${head("الجمهور", "لمن نصمّم", "شخصيات تخطيطية افتراضية وليست نتائج بحث")}
<div class="cols4">${[["ليلى، 29", "مهنية في المجال الإبداعي", "تريد مكاناً ثالثاً جميلاً بقدر ما هو لذيذ، وفيه مقاعد تستحق الجلوس.", "لاتيه الساعة الذهبية، كولد برو غيمة الورد"], ["دانيال، 38", "موظف هجين وأب", "فلات وايت ممتاز يُعتمد عليه، وساعة هادئة بين الاجتماعات.", "فلات وايت، كابتشينو طريق الحرير"], ["مي، 22", "طالبة وصانعة محتوى", "نكهات مرحة، وإضاءة جميلة للتصوير، وأسعار عادلة.", "لاتيه غيمة اليوبي، سمسم منتصف الليل"], ["عمر، 45", "شريك محتمل", "مفهوم مميز بمعايير موثّقة واقتصاديات صادقة.", "برنامج الشراكة والامتياز"]].map(([n, r, b, h]) => `<div class="card"><h3>${n}</h3><span class="chip">${r}</span><p>${b}</p><p class="fine">يجرّب: ${h}</p></div>`).join("")}</div>
<div class="cols2" style="margin-top:20px">${card("موقعنا بين المنافسين", ul(["السلاسل العالمية: مريحة لكن نكهاتها عامة، ونحن أكثر تميزاً ودفئاً.", "مقاهي الموجة الثالثة: قهوة ممتازة لكنها صارمة، ونحن بالحرفية نفسها مع منيو ودّي.", "علامات الحلويات والشاي الرائجة: ممتعة لكن القهوة فيها ثانوية، ونحن نبني الاتجاهات على إسبريسو حقيقي."]))}${card("ما يميّزنا", ul(["14 مشروباً أصلياً بوصفات موثّقة.", "فكرة بصرية واحدة: الشمس تشرق من الكوب.", "نظام تشغيل كامل: معايير وإجراءات وتدريب وجودة.", "صدق تام فيما جُرِّب وما هو مقترح."]))}</div>`);
add("فكرة العلامة", `${head("اقرأ هذا أولاً", "الوضع الحقيقي لهذه العلامة", "ما أُنجز وما هو تقديري وما ينقص")}
<div class="cols3">${card("✓ أُنجز في هذا الدليل", ul(["استراتيجية العلامة والاسم والسلوغن", "الشعار والألوان والخطوط والنمط والأيقونات", "تصاميم الأكواب والتغليف والأزياء واللافتات والمنيو", "تصور المحل والمخططات والمعدات والتجهيز", "41 صنفاً بوصفات مقترحة وأحجام", "دليل التشغيل والتدريب والجودة", "هيكل باقة الامتياز وسيناريوهات اقتصادية"]))}${card("≈ تقديري", ul(["تكاليف المكونات وأسعار البيع", "ميزانيات المعدات والتجهيز", "كل سيناريوهات الإيرادات والأرباح", "أبعاد الأكواب (تُؤكَّد مع المورّد)", "مستوى الرسوم (غير محدد)"]))}${card("✗ مطلوب قبل الفتح أو الامتياز", ul(["تجربة كل وصفة 3 مرات مع لجنة تذوّق", "بحث رسمي عن العلامة التجارية في كل بلد", "عروض أسعار من الموردين لكل البنود", "محامٍ محلي لمتطلبات الإفصاح عن الامتياز", "اعتماد سلامة الغذاء والمسببات للحساسية والتراخيص", "فرع تجريبي يُنتج بيانات مبيعات حقيقية"]), "warn")}</div>`);

