// ------------------------------------------------------------------ 5. PDF + overflow check
const { chromium } = require("playwright");
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto("file://" + htmlPath, { waitUntil: "load" });
await page.evaluate(() => document.fonts.ready);
const overflow = await page.evaluate(() => [...document.querySelectorAll(".page")].map((p, i) => {
  const lim = p.getBoundingClientRect().bottom - 34; let max = 0;
  p.querySelectorAll("*").forEach((e) => { if (e.closest(".ft") || e.closest(".arc") || e.closest(".cv-arc") || e.classList.contains("menu-fine")) return; const r = e.getBoundingClientRect(); if (r.height > 0) max = Math.max(max, r.bottom); });
  return max > lim + 1 ? { page: i + 1, section: p.dataset.section, over: Math.round(max - lim) } : null;
}).filter(Boolean));
const pdfName = `${SLUG}-brand-franchise-kit-ar.pdf`;
await page.pdf({ path: path.join(KIT, pdfName), width: "1280px", height: "720px", printBackground: true });
console.log(`PDF: ${pdfName} — ${pages.length} pages`);
console.log(overflow.length ? "OVERFLOW: " + JSON.stringify(overflow) : "No page overflow detected");

// ------------------------------------------------------------------ 6. PNG exports (Chromium so Arabic text uses the real font) + data
const PNG = path.join(KIT, "assets-png");
