writeFileSync(base, `<!doctype html><meta charset="utf-8"><style>${css.split("@page")[0]}body{margin:0;background:transparent}svg{display:block}</style><body></body>`);
const shot = await browser.newPage({ viewport: { width: 1000, height: 800 }, deviceScaleFactor: 2 });
await shot.goto("file://" + base);
let n = 0;
for (const dir of ["logo", "mockups", "drinks", "cafe", "icons", "kit"]) {
  mkdirSync(path.join(PNG, dir), { recursive: true });
  for (const f of readdirSync(path.join(ASSETS, dir)).filter((x) => x.endsWith(".svg"))) {
    const svg = readFileSync(path.join(ASSETS, dir, f), "utf8").replace(/<\?xml[^>]*\?>/, "");
    const [w, h] = (svg.match(/viewBox="0 0 ([\d.]+) ([\d.]+)"/) ?? []).slice(1).map(Number);
    await shot.setViewportSize({ width: Math.ceil(w), height: Math.ceil(h) });
    await shot.evaluate((s) => { document.body.innerHTML = s; }, svg);
    await shot.evaluate(() => document.fonts.ready);
    await shot.screenshot({ path: path.join(PNG, dir, f.replace(".svg", ".png")), omitBackground: dir === "logo" || dir === "icons" });
    n++;
  }
}
await browser.close();
console.log(`PNG exports: ${n}`);
